package com.taskmanager.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.Date; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService {private final SecretKey key; private final long expiration; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.expiration-ms}") long expiration){byte[] b=secret.getBytes(StandardCharsets.UTF_8);if(b.length<32)throw new IllegalArgumentException("JWT_SECRET must contain at least 32 UTF-8 bytes");key=Keys.hmacShaKeyFor(b);this.expiration=expiration;} public String generate(String subject){long now=System.currentTimeMillis();return Jwts.builder().subject(subject).issuedAt(new Date(now)).expiration(new Date(now+expiration)).signWith(key).compact();} public String subject(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();}}
